    int delay = baseDelay * attempt;
    if (serverBusy && delay < 600)
        delay *= 2;
    if (delay > 3600)
        delay = 3600;
    else if (delay < 1)
        delay = 1;
    else if (attempt > 7)
        delay += 100;
    return delay;
}

